25	/**
26	 * Stages the exact published evidence with the aggregate rolled back to its
27	 * pre-append membership, so the append transaction itself is still replayed
28	 * against its real predecessor now that the published aggregate carries the
29	 * Papercups pair.
30	 */
31	async function stagedRoot(): Promise<string> {
32		const directory = await mkdtemp(path.join(os.tmpdir(), 'papercups-aggregate-'));
33		for (const relative of evidenceFiles) {
34			const destination = path.join(directory, relative);
35			await mkdir(path.dirname(destination), { recursive: true });
36			await copyFile(path.join(repositoryRoot, relative), destination);
37		}
38		await rewrite(directory, (members) =>
39			members.filter(
40				(member) =>
41					member.receipt !== REACT_PAPERCUPS_RECEIPT_PATH &&
42					member.receipt !== WITNESS_REACT_PAPERCUPS_RECEIPT_PATH,
43			),
44		);
45		expect(await fixtures(directory)).toHaveLength(16);
46		return directory;
47	}
