49	async function fixtures(directory: string): Promise<Array<Record<string, unknown>>> {
50		const aggregate = JSON.parse(
51			await readFile(path.join(directory, 'evidence/runs/aggregate.json'), 'utf8'),
52		) as { fixtures: Array<Record<string, unknown>> };
53		return aggregate.fixtures;
54	}
