const panLike = createRegExp(digit.and(maybe(charIn(' -'))).times.between(13, 19));
const sha256Hex = createRegExp(
	charIn('0123456789').from('a', 'f').times(64).at.lineStart().at.lineEnd(),
	[caseInsensitive],
);

