	'evidenceBlockers',
	'nestedCompatibleLicense',
	'excludedCommittedDist',
]);
const t124OfficialTreeRowKeys = new Set(['path', 'mode', 'type', 'sha']);
const t138ImmutableFixtureRootKeys = new Set([
	'schemaVersion',
	'id',
	'framework',
	'repository',
	'repositoryUrl',
	'commit',
	'tree',
	'archive',
	'archiveManifestSha256',
	'repositoryIdentity',
	'reliedPaths',
