const t138Repository = 'timlrx/tailwind-nextjs-starter-blog';
const t138Commit = '09ba0550caea03a8c38bc4878d05838d2a57f999';
const t138Tree = '2609b3fc4a63d7bccd8f187d66c141f4a7d3cadf';
const t138ReliedPaths = [
